// Package ulid generates ULIDs (Universally Unique Lexicographically Sortable
// Identifiers): 48 bits of millisecond timestamp followed by 80 random bits,
// encoded as 26 Crockford base32 characters.
package ulid

import (
	"crypto/rand"
	"regexp"
	"sync"
	"time"
)

const alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"

var valid = regexp.MustCompile(`^[0-9A-HJKMNP-TV-Z]{26}$`)

var (
	mu     sync.Mutex
	lastMs uint64
	last   [16]byte
)

// New returns a new ULID for the current time. IDs generated by this process
// are strictly increasing, even within the same millisecond (monotonic mode:
// the random part of the previous ID is incremented).
func New() string { return NewAt(time.Now()) }

// NewAt returns a new ULID for the given time (monotonic, see New).
func NewAt(t time.Time) string {
	mu.Lock()
	defer mu.Unlock()
	ms := uint64(t.UnixMilli())
	var b [16]byte
	if ms <= lastMs && lastMs != 0 {
		// Same (or earlier, clock skew) millisecond: increment the previous ID.
		b = last
		for i := 15; i >= 6; i-- {
			b[i]++
			if b[i] != 0 {
				break
			}
		}
	} else {
		x := ms
		for i := 5; i >= 0; i-- {
			b[i] = byte(x)
			x >>= 8
		}
		if _, err := rand.Read(b[6:]); err != nil {
			panic("ulid: crypto/rand failed: " + err.Error())
		}
		// Leave headroom so increments rarely overflow the random part.
		b[6] &= 0x7f
		lastMs = ms
	}
	last = b
	return encode(b)
}

// Valid reports whether s is a syntactically valid ULID.
func Valid(s string) bool { return valid.MatchString(s) }

func encode(b [16]byte) string {
	// 128 bits -> 26 chars of 5 bits (the first char carries only 3 bits).
	out := make([]byte, 26)
	var acc uint64
	var hi uint64 = uint64(b[0])<<56 | uint64(b[1])<<48 | uint64(b[2])<<40 | uint64(b[3])<<32 |
		uint64(b[4])<<24 | uint64(b[5])<<16 | uint64(b[6])<<8 | uint64(b[7])
	var lo uint64 = uint64(b[8])<<56 | uint64(b[9])<<48 | uint64(b[10])<<40 | uint64(b[11])<<32 |
		uint64(b[12])<<24 | uint64(b[13])<<16 | uint64(b[14])<<8 | uint64(b[15])
	for i := 25; i >= 0; i-- {
		acc = lo & 31
		out[i] = alphabet[acc]
		lo = lo>>5 | hi<<59
		hi >>= 5
	}
	return string(out)
}
